<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
  :root {
    color-scheme: dark;
    --orange: #e95420;
    --panel: #1e1e1e;
    --surface: #2b2b2b;
    --surface-2: #353535;
    --border: #4b4b4b;
    --text: #f5f5f5;
    --muted: #bdbdbd;
  }

  * {
    box-sizing: border-box;
  }

  html, body {
    width: 100%;
    height: 100%;
    margin: 0;
    overflow: hidden;
    font-family: "Segoe UI", Ubuntu, Arial, sans-serif;
    color: var(--text);
    background: #281438;
  }

  button, textarea {
    font: inherit;
  }

  button {
    color: inherit;
  }

  #desktop {
    position: relative;
    width: 100vw;
    height: 100vh;
    min-width: 400px;
    min-height: 300px;
    overflow: hidden;
    background:
      radial-gradient(circle at 74% 38%, rgba(233, 84, 32, .36), transparent 24%),
      radial-gradient(circle at 17% 79%, rgba(119, 41, 83, .62), transparent 35%),
      linear-gradient(135deg, #1b0a2b 0%, #451837 48%, #8e2d36 100%);
  }

  #desktop::before,
  #desktop::after {
    content: "";
    position: absolute;
    pointer-events: none;
    border-radius: 50%;
    border: 3px solid rgba(255, 255, 255, .08);
    transform: rotate(-28deg);
  }

  #desktop::before {
    width: 54vw;
    height: 54vw;
    right: -20vw;
    top: 4vh;
    box-shadow: 0 0 0 54px rgba(255, 255, 255, .018);
  }

  #desktop::after {
    width: 28vw;
    height: 28vw;
    left: -12vw;
    bottom: -8vw;
  }

  #topbar {
    position: absolute;
    inset: 0 0 auto;
    z-index: 1000;
    height: 30px;
    display: flex;
    align-items: center;
    padding: 0 12px;
    background: rgba(20, 20, 20, .96);
    box-shadow: 0 1px 3px rgba(0, 0, 0, .45);
    font-size: 13px;
    user-select: none;
  }

  #activities {
    font-weight: 600;
  }

  #clock {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    font-weight: 600;
  }

  #status {
    margin-left: auto;
    color: #ddd;
    letter-spacing: 3px;
  }

  #desktop-icons {
    position: absolute;
    top: 54px;
    right: 20px;
    display: grid;
    gap: 18px;
    z-index: 1;
  }

  .desktop-icon {
    width: 78px;
    padding: 8px 4px;
    border: 0;
    border-radius: 8px;
    background: transparent;
    text-align: center;
    cursor: default;
  }

  .desktop-icon:hover {
    background: rgba(255, 255, 255, .12);
  }

  .desktop-glyph {
    display: block;
    width: 46px;
    height: 38px;
    margin: 0 auto 7px;
    border-radius: 4px;
    background: linear-gradient(#f5b33d 0 23%, #d8871e 23%);
    box-shadow: 0 4px 8px rgba(0, 0, 0, .28);
  }

  .desktop-label {
    font-size: 12px;
    text-shadow: 0 1px 3px #000;
  }

  #taskbar {
    position: absolute;
    z-index: 1100;
    left: 50%;
    bottom: 12px;
    transform: translateX(-50%);
    display: flex;
    gap: 8px;
    padding: 8px;
    border: 1px solid rgba(255, 255, 255, .16);
    border-radius: 14px;
    background: rgba(28, 24, 30, .88);
    box-shadow: 0 8px 28px rgba(0, 0, 0, .45);
    backdrop-filter: blur(12px);
  }

  .launcher {
    position: relative;
    width: 50px;
    height: 50px;
    border: 0;
    border-radius: 11px;
    background: transparent;
    cursor: pointer;
    transition: background .15s, transform .15s;
  }

  .launcher:hover,
  .launcher.active {
    background: rgba(255, 255, 255, .13);
    transform: translateY(-2px);
  }

  .launcher.active::after {
    content: "";
    position: absolute;
    bottom: 2px;
    left: 50%;
    width: 5px;
    height: 5px;
    transform: translateX(-50%);
    border-radius: 50%;
    background: var(--orange);
  }

  .launcher-icon {
    position: relative;
    display: block;
    margin: auto;
  }

  #open-files .launcher-icon {
    width: 34px;
    height: 27px;
    margin-top: 9px;
    border-radius: 4px;
    background: linear-gradient(#f6b847 0 25%, #d8891d 25%);
    box-shadow: 0 3px 6px rgba(0, 0, 0, .35);
  }

  #open-files .launcher-icon::before {
    content: "";
    position: absolute;
    top: -4px;
    left: 3px;
    width: 15px;
    height: 7px;
    border-radius: 3px 3px 0 0;
    background: #f6b847;
  }

  #open-notepad .launcher-icon {
    width: 29px;
    height: 35px;
    margin-top: 3px;
    border-radius: 3px;
    background:
      repeating-linear-gradient(to bottom, transparent 0 6px, #88a7ca 7px 8px),
      #eef3f7;
    box-shadow: inset 5px 0 #e95420, 0 3px 6px rgba(0, 0, 0, .35);
  }

  .window {
    position: absolute;
    z-index: 10;
    display: none;
    flex-direction: column;
    width: min(720px, calc(100vw - 40px));
    height: min(500px, calc(100vh - 100px));
    min-width: 360px;
    min-height: 240px;
    overflow: hidden;
    resize: both;
    border: 1px solid #555;
    border-radius: 10px;
    background: var(--surface);
    box-shadow: 0 20px 60px rgba(0, 0, 0, .55);
  }

  .window.visible {
    display: flex;
  }

  #files-window {
    top: 70px;
    left: 8vw;
  }

  #notepad-window {
    top: 92px;
    left: max(22vw, 100px);
  }

  .titlebar {
    flex: 0 0 38px;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 8px 0 14px;
    background: linear-gradient(#3b3b3b, #303030);
    border-bottom: 1px solid #191919;
    cursor: grab;
    user-select: none;
  }

  .titlebar:active {
    cursor: grabbing;
  }

  .window-title {
    flex: 1;
    text-align: center;
    font-size: 13px;
    font-weight: 600;
  }

  .win-close {
    width: 25px;
    height: 25px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: #555;
    color: transparent;
    cursor: pointer;
    position: relative;
  }

  .win-close::before,
  .win-close::after {
    content: "";
    position: absolute;
    top: 12px;
    left: 7px;
    width: 11px;
    height: 1.5px;
    background: white;
  }

  .win-close::before {
    transform: rotate(45deg);
  }

  .win-close::after {
    transform: rotate(-45deg);
  }

  .win-close:hover {
    background: #c9472b;
  }

  .toolbar {
    flex: 0 0 44px;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 10px;
    border-bottom: 1px solid #1b1b1b;
    background: #292929;
  }

  #files-up,
  #new-tab {
    min-width: 34px;
    height: 30px;
    border: 1px solid #555;
    border-radius: 6px;
    background: #3c3c3c;
    cursor: pointer;
  }

  #files-up:hover,
  #new-tab:hover {
    background: #4a4a4a;
  }

  #files-up:disabled {
    opacity: .4;
    cursor: default;
  }

  #files-path {
    flex: 1;
    min-width: 0;
    height: 30px;
    padding: 6px 11px;
    overflow: hidden;
    border: 1px solid #4b4b4b;
    border-radius: 6px;
    background: #1f1f1f;
    color: #eee;
    font-family: Consolas, monospace;
    font-size: 13px;
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  .files-body {
    display: flex;
    flex: 1;
    min-height: 0;
  }

  .sidebar {
    flex: 0 0 150px;
    padding: 10px 7px;
    border-right: 1px solid #444;
    background: #252525;
  }

  .side-item {
    display: block;
    width: 100%;
    padding: 8px 10px;
    border: 0;
    border-radius: 5px;
    background: transparent;
    color: #ddd;
    text-align: left;
    cursor: pointer;
  }

  .side-item:hover {
    background: #3b3b3b;
  }

  #files-list {
    flex: 1;
    min-width: 0;
    overflow: auto;
    padding: 14px;
    display: grid;
    align-content: start;
    grid-template-columns: repeat(auto-fill, minmax(105px, 1fr));
    gap: 10px;
    background: #303030;
  }

  .fs-item {
    min-height: 82px;
    padding: 50px 7px 8px;
    overflow: hidden;
    position: relative;
    border: 1px solid transparent;
    border-radius: 7px;
    background: transparent;
    color: #eee;
    text-align: center;
    text-overflow: ellipsis;
    white-space: nowrap;
    cursor: default;
  }

  .fs-item:hover,
  .fs-item:focus {
    outline: none;
    border-color: #5d6f88;
    background: #3e4855;
  }

  .fs-item::before {
    content: "";
    position: absolute;
    top: 18px;
    left: 50%;
    width: 42px;
    height: 29px;
    transform: translateX(-50%);
    border-radius: 4px;
    background: linear-gradient(#f5b33d 0 25%, #d8871e 25%);
    box-shadow: 0 3px 5px rgba(0, 0, 0, .3);
  }

  .fs-item.folder::after {
    content: "";
    position: absolute;
    top: 14px;
    left: calc(50% - 17px);
    width: 18px;
    height: 8px;
    border-radius: 3px 3px 0 0;
    background: #f5b33d;
  }

  .fs-item.file::before {
    width: 31px;
    height: 38px;
    top: 10px;
    border-radius: 3px;
    background:
      repeating-linear-gradient(to bottom, transparent 0 7px, #9aa7b4 8px 9px),
      #e5e9ed;
  }

  .notepad-tools {
    justify-content: space-between;
  }

  #new-tab {
    padding: 0 12px;
    font-weight: 600;
  }

  #tabs {
    flex: 1;
    min-width: 0;
    display: flex;
    gap: 3px;
    overflow-x: auto;
  }

  .tab {
    flex: 0 0 auto;
    max-width: 150px;
    min-width: 78px;
    height: 31px;
    padding: 6px 12px;
    overflow: hidden;
    border: 1px solid #4b4b4b;
    border-bottom: 0;
    border-radius: 7px 7px 0 0;
    background: #242424;
    color: #bbb;
    text-overflow: ellipsis;
    white-space: nowrap;
    cursor: pointer;
  }

  .tab.active {
    background: #454545;
    color: white;
    box-shadow: inset 0 2px var(--orange);
  }

  #editor {
    display: block;
    flex: 1;
    width: 100%;
    min-height: 0;
    resize: none;
    padding: 18px 20px;
    border: 0;
    outline: 0;
    background: #202124;
    color: #f1f1f1;
    caret-color: #ff8a5c;
    font: 15px/1.55 Consolas, "Courier New", monospace;
    tab-size: 4;
  }

  .statusbar {
    flex: 0 0 24px;
    padding: 4px 10px;
    border-top: 1px solid #414141;
    background: #292929;
    color: #aaa;
    font-size: 11px;
    text-align: right;
  }

  @media (max-width: 560px) {
    .sidebar {
      display: none;
    }

    #files-window,
    #notepad-window {
      left: 20px;
    }
  }
</style>
</head>
<body>
<div id="desktop">
  <div id="topbar">
    <span id="activities">Activities</span>
    <span id="clock"></span>
    <span id="status">● ◉ ⏻</span>
  </div>

  <div id="desktop-icons" aria-hidden="true">
    <div class="desktop-icon">
      <span class="desktop-glyph"></span>
      <span class="desktop-label">Home</span>
    </div>
  </div>

  <section id="files-window" class="window" aria-label="Files">
    <div class="titlebar">
      <span class="window-title">Files</span>
      <button class="win-close" aria-label="Close Files">Close</button>
    </div>
    <div class="toolbar">
      <button id="files-up" aria-label="Go to parent folder" title="Parent folder">↑</button>
      <div id="files-path">/</div>
    </div>
    <div class="files-body">
      <aside class="sidebar">
        <button class="side-item" data-path="/">⌂ Computer</button>
        <button class="side-item" data-path="/home/user">⌂ Home</button>
        <button class="side-item" data-path="/home/user/Documents">▤ Documents</button>
        <button class="side-item" data-path="/home/user/Downloads">↓ Downloads</button>
        <button class="side-item" data-path="/home/user/Pictures">▧ Pictures</button>
      </aside>
      <main id="files-list" aria-label="Folder contents"></main>
    </div>
    <div class="statusbar" id="files-status"></div>
  </section>

  <section id="notepad-window" class="window" aria-label="Notepad">
    <div class="titlebar">
      <span class="window-title">Notepad</span>
      <button class="win-close" aria-label="Close Notepad">Close</button>
    </div>
    <div class="toolbar notepad-tools">
      <div id="tabs" aria-label="Document tabs"></div>
      <button id="new-tab" title="New tab" aria-label="Create new tab">＋</button>
    </div>
    <textarea id="editor" spellcheck="true" aria-label="Notepad editor"></textarea>
    <div class="statusbar" id="notepad-status">Saved locally</div>
  </section>

  <nav id="taskbar" aria-label="Applications">
    <button id="open-files" class="launcher" title="Files" aria-label="Open Files">
      <span class="launcher-icon"></span>
    </button>
    <button id="open-notepad" class="launcher" title="Notepad" aria-label="Open Notepad">
      <span class="launcher-icon"></span>
    </button>
  </nav>
</div>

<script>
(() => {
  "use strict";

  const desktop = document.getElementById("desktop");
  const filesWindow = document.getElementById("files-window");
  const notepadWindow = document.getElementById("notepad-window");
  const openFiles = document.getElementById("open-files");
  const openNotepad = document.getElementById("open-notepad");

  let topZ = 20;

  function showWindow(win, launcher) {
    win.classList.add("visible");
    launcher.classList.add("active");
    bringToFront(win);
  }

  function hideWindow(win, launcher) {
    win.classList.remove("visible");
    launcher.classList.remove("active");
  }

  function bringToFront(win) {
    topZ += 1;
    win.style.zIndex = topZ;
  }

  openFiles.addEventListener("click", () => showWindow(filesWindow, openFiles));
  openNotepad.addEventListener("click", () => showWindow(notepadWindow, openNotepad));

  filesWindow.querySelector(".win-close").addEventListener("click", () => {
    hideWindow(filesWindow, openFiles);
  });

  notepadWindow.querySelector(".win-close").addEventListener("click", () => {
    hideWindow(notepadWindow, openNotepad);
  });

  document.querySelectorAll(".window").forEach(win => {
    win.addEventListener("pointerdown", () => bringToFront(win));
    makeDraggable(win);
  });

  function makeDraggable(win) {
    const handle = win.querySelector(".titlebar");
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let startLeft = 0;
    let startTop = 0;

    handle.addEventListener("pointerdown", event => {
      if (event.target.closest(".win-close")) return;
      dragging = true;
      bringToFront(win);
      const rect = win.getBoundingClientRect();
      startX = event.clientX;
      startY = event.clientY;
      startLeft = rect.left;
      startTop = rect.top;
      handle.setPointerCapture(event.pointerId);
      event.preventDefault();
    });

    handle.addEventListener("pointermove", event => {
      if (!dragging) return;
      const maxLeft = Math.max(0, desktop.clientWidth - 120);
      const maxTop = Math.max(30, desktop.clientHeight - 80);
      const left = Math.min(maxLeft, Math.max(0, startLeft + event.clientX - startX));
      const top = Math.min(maxTop, Math.max(30, startTop + event.clientY - startY));
      win.style.left = left + "px";
      win.style.top = top + "px";
    });

    const stop = event => {
      dragging = false;
      if (handle.hasPointerCapture(event.pointerId)) {
        handle.releasePointerCapture(event.pointerId);
      }
    };

    handle.addEventListener("pointerup", stop);
    handle.addEventListener("pointercancel", stop);
  }

  const fileSystem = {
    "/": [
      { name: "bin", type: "folder" },
      { name: "etc", type: "folder" },
      { name: "home", type: "folder" },
      { name: "lib", type: "folder" },
      { name: "opt", type: "folder" },
      { name: "tmp", type: "folder" },
      { name: "usr", type: "folder" },
      { name: "var", type: "folder" }
    ],
    "/bin": [
      { name: "bash", type: "file" },
      { name: "cat", type: "file" },
      { name: "ls", type: "file" }
    ],
    "/etc": [
      { name: "network", type: "folder" },
      { name: "hosts", type: "file" },
      { name: "passwd", type: "file" }
    ],
    "/etc/network": [
      { name: "interfaces", type: "file" }
    ],
    "/home": [
      { name: "user", type: "folder" }
    ],
    "/home/user": [
      { name: "Documents", type: "folder" },
      { name: "Downloads", type: "folder" },
      { name: "Pictures", type: "folder" },
      { name: "Music", type: "folder" },
      { name: "Videos", type: "folder" },
      { name: "welcome.txt", type: "file" }
    ],
    "/home/user/Documents": [
      { name: "Notes.txt", type: "file" },
      { name: "Projects", type: "folder" },
      { name: "Resume.pdf", type: "file" }
    ],
    "/home/user/Documents/Projects": [
      { name: "desktop-demo", type: "folder" },
      { name: "ideas.md", type: "file" }
    ],
    "/home/user/Documents/Projects/desktop-demo": [
      { name: "README.md", type: "file" },
      { name: "app.html", type: "file" }
    ],
    "/home/user/Downloads": [
      { name: "archive.zip", type: "file" },
      { name: "wallpaper.png", type: "file" }
    ],
    "/home/user/Pictures": [
      { name: "Screenshots", type: "folder" },
      { name: "mountains.jpg", type: "file" }
    ],
    "/home/user/Pictures/Screenshots": [
      { name: "desktop.png", type: "file" }
    ],
    "/home/user/Music": [],
    "/home/user/Videos": [],
    "/lib": [
      { name: "modules", type: "folder" }
    ],
    "/lib/modules": [],
    "/opt": [],
    "/tmp": [],
    "/usr": [
      { name: "bin", type: "folder" },
      { name: "lib", type: "folder" },
      { name: "local", type: "folder" },
      { name: "share", type: "folder" }
    ],
    "/usr/bin": [],
    "/usr/lib": [],
    "/usr/local": [],
    "/usr/share": [],
    "/var": [
      { name: "cache", type: "folder" },
      { name: "log", type: "folder" },
      { name: "tmp", type: "folder" }
    ],
    "/var/cache": [],
    "/var/log": [
      { name: "system.log", type: "file" }
    ],
    "/var/tmp": []
  };

  const filesPath = document.getElementById("files-path");
  const filesList = document.getElementById("files-list");
  const filesUp = document.getElementById("files-up");
  const filesStatus = document.getElementById("files-status");
  let currentPath = "/";

  function childPath(parent, name) {
    return parent === "/" ? "/" + name : parent + "/" + name;
  }

  function navigate(path) {
    if (!Object.prototype.hasOwnProperty.call(fileSystem, path)) return;
    currentPath = path;
    filesPath.textContent = path;
    filesPath.title = path;
    filesUp.disabled = path === "/";
    filesList.replaceChildren();

    const entries = fileSystem[path];
    entries.forEach(entry => {
      const item = document.createElement("div");
      item.className = "fs-item " + entry.type;
      item.textContent = entry.name;
      item.title = entry.name;
      item.tabIndex = 0;

      if (entry.type === "folder") {
        const openFolder = () => navigate(childPath(path, entry.name));
        item.addEventListener("dblclick", openFolder);
        item.addEventListener("keydown", event => {
          if (event.key === "Enter") openFolder();
        });
      }

      filesList.appendChild(item);
    });

    filesStatus.textContent =
      entries.length + (entries.length === 1 ? " item" : " items");
  }

  filesUp.addEventListener("click", () => {
    if (currentPath === "/") return;
    const pieces = currentPath.split("/").filter(Boolean);
    pieces.pop();
    navigate(pieces.length ? "/" + pieces.join("/") : "/");
  });

  document.querySelectorAll(".side-item").forEach(item => {
    item.addEventListener("click", () => navigate(item.dataset.path));
  });

  navigate("/");

  const storageKey = "ubuntu-desktop-notepad-tabs-v1";
  const tabsElement = document.getElementById("tabs");
  const newTabButton = document.getElementById("new-tab");
  const editor = document.getElementById("editor");
  const notepadStatus = document.getElementById("notepad-status");

  let notepadState = loadNotepadState();

  function defaultState() {
    return {
      activeId: "tab-1",
      nextId: 2,
      tabs: [
        { id: "tab-1", title: "Untitled 1", content: "" }
      ]
    };
  }

  function loadNotepadState() {
    try {
      const saved = localStorage.getItem(storageKey);
      if (!saved) return defaultState();

      const parsed = JSON.parse(saved);
      if (!parsed || !Array.isArray(parsed.tabs) || parsed.tabs.length === 0) {
        return defaultState();
      }

      parsed.tabs = parsed.tabs.map((tab, index) => ({
        id: String(tab.id || "restored-" + index),
        title: String(tab.title || "Untitled " + (index + 1)),
        content: typeof tab.content === "string" ? tab.content : ""
      }));

      if (!parsed.tabs.some(tab => tab.id === parsed.activeId)) {
        parsed.activeId = parsed.tabs[0].id;
      }

      if (!Number.isInteger(parsed.nextId) || parsed.nextId < 1) {
        parsed.nextId = parsed.tabs.length + 1;
      }

      return parsed;
    } catch {
      return defaultState();
    }
  }

  function saveNotepadState() {
    try {
      localStorage.setItem(storageKey, JSON.stringify(notepadState));
      notepadStatus.textContent = "Saved locally";
    } catch {
      notepadStatus.textContent = "Local save unavailable";
    }
  }

  function activeTab() {
    return notepadState.tabs.find(tab => tab.id === notepadState.activeId);
  }

  function renderTabs() {
    tabsElement.replaceChildren();

    notepadState.tabs.forEach(tabData => {
      const tab = document.createElement("button");
      tab.type = "button";
      tab.className = "tab" +
        (tabData.id === notepadState.activeId ? " active" : "");
      tab.textContent = tabData.title;
      tab.title = tabData.title;
      tab.dataset.id = tabData.id;
      tab.addEventListener("click", () => switchTab(tabData.id));
      tabsElement.appendChild(tab);
    });

    const selected = activeTab();
    editor.value = selected ? selected.content : "";
  }

  function switchTab(id) {
    const current = activeTab();
    if (current) current.content = editor.value;
    notepadState.activeId = id;
    saveNotepadState();
    renderTabs();
    editor.focus();
  }

  newTabButton.addEventListener("click", () => {
    const idNumber = notepadState.nextId++;
    const tab = {
      id: "tab-" + idNumber + "-" + Date.now(),
      title: "Untitled " + idNumber,
      content: ""
    };
    notepadState.tabs.push(tab);
    notepadState.activeId = tab.id;
    saveNotepadState();
    renderTabs();
    editor.focus();
  });

  editor.addEventListener("input", () => {
    const current = activeTab();
    if (!current) return;
    current.content = editor.value;
    saveNotepadState();
  });

  renderTabs();
  saveNotepadState();

  function updateClock() {
    const now = new Date();
    document.getElementById("clock").textContent =
      now.toLocaleDateString(undefined, {
        weekday: "short",
        month: "short",
        day: "numeric"
      }) + "  " +
      now.toLocaleTimeString(undefined, {
        hour: "2-digit",
        minute: "2-digit"
      });
  }

  updateClock();
  setInterval(updateClock, 30000);

  showWindow(filesWindow, openFiles);
})();
